const icons={shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/>',home:'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3Z"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 8v8m3-8v8m4-8v8m3-8v8"/>',family:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-4a5 5 0 0 0-2-4"/>',list:'<path d="M5 3h14v18l-7-4-7 4Z"/><path d="m8 10 3 3 5-5"/>',cook:'<path d="M6 14a5 5 0 0 1-2-9 4 4 0 0 1 7-1 5 5 0 0 1 9 4 4 4 0 0 1-2 6v7H6Z"/><path d="M6 17h12"/>',heart:'<path d="M20 5c-3-3-7-1-8 1-1-2-5-4-8-1-5 5 8 15 8 15S25 10 20 5Z"/><path d="M5 11h4l2-3 2 6 2-3h4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5Zm5 4h4"/>',sound:'<path d="m10 4-6 5H1v6h3l6 5Zm5 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',phone:'<path d="m7 3 3 5-3 3a16 16 0 0 0 6 6l3-3 5 3c0 5-5 6-10 3S2 12 3 7Z"/>',qr:'<path d="M3 3h6v6H3Zm12 0h6v6h-6ZM3 15h6v6H3Zm12 0h3v3h3v3h-6Zm6-3h-3m-6 0v3"/>'};const ico=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[n]||icons.shield)+'</svg>';let savedProfiles=[],approvedRecipes=[];let page='home',arabic=false,selected=['Peanuts','Sesame / طحينة','Gluten / Wheat'],policy='strict',memberName='Sara',removed=false,filter='Everyone',scanStep=2,stream=null;const $=s=>document.querySelector(s),txt=(e,a)=>arabic?a:e;const go=p=>{if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}page=p;render();window.scrollTo(0,0)};const toast=m=>{$('#toast').textContent=m;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)};const speak=t=>{if('speechSynthesis'in window){speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang=arabic?'ar-JO':'en-GB';speechSynthesis.speak(u)}else toast('Read aloud is unavailable in this browser')};
const art='<svg class="hero-art" viewBox="0 0 300 260" fill="none" xmlns="http://www.w3.org/2000/svg" style="stroke:none"><circle cx="175" cy="143" r="108" fill="#d9e9d6"/><ellipse cx="172" cy="237" rx="102" ry="12" fill="#c6dcc7"/><path d="M76 125h176l-24 105H101Z" fill="#c69c6c"/><path d="M91 147h145m-139 24h133m-127 24h121m-114 23h109M119 134l13 92m16-93 5 96m20-96-2 96m28-96-10 94m32-92-14 90" stroke="#e2bf92" stroke-width="5"/><path d="M113 132c-8-36 2-81 22-92 16 24 23 60 12 90" fill="#ebbd75"/><path d="m124 66 14 7m-18 13 20 9m-20 10 19 10" stroke="#cc944e" stroke-width="4"/><path d="M204 134c-5-24-3-45 12-56 19-13 27-34 39-33 10 14 3 34-6 46 16-8 28-7 34 0-3 19-31 41-57 45" fill="#70a77f"/><path d="m220 131 29-66" stroke="#39755b" stroke-width="3"/><rect x="153" y="81" width="43" height="62" rx="6" fill="#f7faf3" transform="rotate(9 153 81)"/><path d="m153 82 11-14 31 5 1 14" fill="#80b0a0"/><rect x="162" y="103" width="21" height="22" rx="3" fill="#b8d5c6"/><circle cx="95" cy="129" r="23" fill="#dc7e5c"/><path d="m94 106 3-12m0 6c-13-8-15-2-15-2" stroke="#5a8054" stroke-width="3"/><circle cx="197" cy="141" r="20" fill="#e6b755"/><path d="M63 154c-12-24-24-25-24-25 0 20 10 34 24 34m1-17c-5-32 1-41 1-41 17 23 13 40-1 50" fill="#84b398"/><circle cx="235" cy="187" r="30" fill="#fff"/><path d="m234 165-16 6v14c0 14 16 23 16 23s17-9 17-23v-14Z" fill="#0d9488"/><path d="m226 185 6 6 11-13" stroke="white" stroke-width="3" stroke-linecap="round"/></svg>';
const navs=[['home','home','Overview','الرئيسية'],['scan','scan','Scan a product','مسح المنتج'],['family','family','Family circle','العائلة'],['safe','list','Safe list','القائمة الآمنة'],['cook','cook','Tell the cook','أخبر الطاهي']];
function render(){document.documentElement.dir=arabic?'rtl':'ltr';document.documentElement.lang=arabic?'ar':'en';$('#app').innerHTML='<aside class="sidebar"><button class="logo" onclick="go(&quot;home&quot;)"><span class="logo-mark">'+ico('shield')+'</span>wiqaya <small>وقاية</small></button><div class="tagline">A LITTLE MORE PEACE OF MIND</div><div class="nav-label">YOUR FAMILY SPACE</div><nav class="nav">'+navs.map(([p,i,e,a])=>'<button class="'+(page===p?'active':'')+'" onclick="go(&quot;'+p+'&quot;)">'+ico(i)+txt(e,a)+(p==='family'?'<span class="count">3</span>':'')+'</button>').join('')+'</nav><div class="sidebar-bottom"><div class="circle-mini"><div style="font-size:11px;font-weight:700"><span class="dot"></span> The Al-Khatib circle</div><div class="mini-avatars"><span class="avatar">👧🏻</span><span class="avatar purple">👦🏻</span><span class="avatar teal">👵🏻</span></div><small style="color:#7b8b84">Together, wherever you are.</small></div><button class="sidebar-foot" onclick="go(&quot;onboarding&quot;)">'+ico('lock')+' Privacy & your data</button></div></aside><div class="shell"><header class="topbar"><div class="crumb">'+ico('home')+' <span>/</span> '+txt('Your family space','مساحة عائلتك')+'</div><div class="top-actions"><button class="language" onclick="arabic=!arabic;render()"><b>EN</b> &nbsp; | &nbsp; عربي</button><button class="emergency-top" onclick="go(&quot;emergency&quot;)">'+ico('heart')+' &nbsp; '+txt('Emergency','طوارئ')+'</button><span class="avatar teal" style="width:34px;height:34px;font-size:17px">👩🏻</span></div></header><main class="main">'+views[page]()+'<footer class="bottom-note"><span>'+ico('lock')+' &nbsp; On-Device Profile • Zero Data Shared</span><span>Made with care, for families in Jordan <span style="color:#0d9488">♡</span></span></footer><div class="prototype">Interactive prototype · sample profiles and scan results · encrypted sync is not connected</div></main></div><nav class="mobile-nav">'+navs.map(([p,i,e,a])=>'<button class="'+(page===p?'active':'')+'" onclick="go(&quot;'+p+'&quot;)">'+ico(i)+txt(e,a)+'</button>').join('')+'</nav>'}
const heading=(ey,h,p,extra='')=>'<div class="heading"><div><div class="eyebrow">'+ey+'</div><h1>'+h+'</h1><p>'+p+'</p></div>'+extra+'</div>';
const member=(name,emoji,cls,chips,desc)=>'<button class="member" onclick="memberName=&quot;'+name+'&quot;;go(&quot;profile&quot;)"><span class="arrow">›</span><div class="member-head"><div class="avatar '+cls+'">'+emoji+'</div><div><h3>'+name+'</h3><p>'+desc+'</p></div></div><div class="chips">'+chips+'</div><div class="policy">'+ico('shield')+' '+(name==='Sara'?'Strictly avoids traces':'Traces need a second look')+'</div></button>';
const views={home:()=>heading(txt('A LITTLE CARE. EVERY DAY.','رعاية صغيرة. كل يوم.'),txt('Good morning, Mama 👋','صباح الخير، ماما 👋'),txt('A little more confidence in every bite.','اطمئنان أكثر مع كل لقمة.'),'<span class="date">Saturday, 24 October</span>')+'<div class="dashboard"><div><section class="hero"><div class="hero-text"><h2>'+txt('Good food.<br>Safer little moments.','طعام طيب.<br>لحظات أكثر أماناً.')+'</h2><p>'+txt('Check a label. Catch the hidden things.<br>Keep the people you love a little safer.','افحص الملصق، واكتشف المكونات الخفية.<br>واحمِ من تحب.')+'</p><button class="primary" onclick="go(&quot;scan&quot;)">'+ico('scan')+' '+txt('Scan a product','مسح المنتج')+' '+ico('arrow')+'</button><div style="font-size:9px;color:#779385;margin-top:9px">Barcode or ingredient label • مسح المنتج</div></div>'+art+'</section><div class="section-title"><h2>'+txt('Your little circle','دائرتك الصغيرة')+' <span style="font-size:11px;color:#93a097;font-weight:400"> / عائلتك</span></h2><button class="text-button" onclick="go(&quot;family&quot;)">Manage family ↗</button></div><div class="family-row">'+member('Sara','👧🏻','', '<span class="chip rose">Peanuts</span><span class="chip rose">Sesame</span><span class="chip lilac">Celiac</span>','A little explorer, age 7')+member('Omar','👦🏻','purple','<span class="chip rose">Cow’s milk</span><span class="chip lilac">Halal</span>','Big adventures, age 4')+'</div><div class="section-title"><h2>'+txt('A little help, right here','مساعدة في متناول يدك')+'</h2></div><div class="quick-grid"><button class="quick" onclick="go(&quot;safe&quot;)"><span class="icon-box">'+ico('list')+'</span><h3>Family safe list ↗</h3><p>Your trusted go-to groceries</p></button><button class="quick" onclick="go(&quot;cook&quot;)"><span class="icon-box">'+ico('cook')+'</span><h3>Tell the cook ↗</h3><p>Allergies, in their language</p></button><button class="quick" onclick="showInvite()"><span class="icon-box">'+ico('qr')+'</span><h3>Invite a caregiver ↗</h3><p>More hands. The same care.</p></button></div></div><aside class="side-column"><div class="panel"><div class="row spread"><h3>Recently checked</h3><button class="text-button" onclick="go(&quot;safe&quot;)">View all</button></div>'+activity('🌾','Organic oat flakes','Today, 9:42 AM · You','Safe','green','safe')+activity('🍫','Hazelnut wafer','Yesterday · Grandma','Review','amber','verdict')+activity('🥛','Almond drink','Yesterday · You','Safe','green','safe')+'</div><div class="notice"><h3>'+ico('bell')+' A little reminder</h3><p>Sara’s epinephrine pen expires in <b>28 days</b>. A good time to plan ahead.</p><button onclick="go(&quot;profile&quot;)">View emergency plan →</button></div><div class="privacy-card">'+ico('shield')+'<h3>Their health. Your hands.</h3><p>Profiles stay on your device.<br>Only food labels are used for checks.</p><button class="text-button" style="margin-top:12px" onclick="go(&quot;onboarding&quot;)">Our privacy promise ↗</button></div></aside></div>',
family:()=>heading('TOGETHER, WHEREVER YOU ARE',txt('Your family circle','دائرة عائلتك'),'One shared circle of care. No email or password needed.','<button class="primary" onclick="memberName=&quot;&quot;;go(&quot;profile&quot;)">+ Add member</button>')+'<div class="stack"><div class="family-row">'+member('Sara','👧🏻','','<span class="chip rose">Peanuts · Sesame</span><span class="chip lilac">Celiac</span>','Child profile')+member('Omar','👦🏻','purple','<span class="chip rose">Cow’s milk</span><span class="chip lilac">Halal</span>','Child profile')+'</div><div class="big-card row spread"><div><h3>👵🏻 Grandma · Caregiver</h3><p>Can scan products and request a parent’s approval.</p></div><span class="status amber">Demo circle · E2EE planned</span></div><div class="big-card"><h2>Care travels with them.</h2><p>Invite a caregiver via an encrypted QR code, with no login or email required.</p><button class="primary" style="margin-top:20px" onclick="showInvite()">'+ico('qr')+' Invite caregiver</button></div></div>',
profile:()=>heading('SET UP IN UNDER A MINUTE',txt('A little about '+(memberName||'your child'),'ملف طفلك'),'The things to look out for, in one place.')+'<form class="content big-card" onsubmit="event.preventDefault();saveProfile()"><label class="field" for="name">Child’s name / اسم الطفل</label><input id="name" type="text" required maxlength="40" value="'+memberName+'"><label class="field">Allergens to avoid</label><div class="allergen-grid">'+['Peanuts','Cow’s Milk','Eggs','Sesame / طحينة','Gluten / Wheat','Pine Nuts / صنوبر','Tree Nuts','Soy','Fish','Crustaceans','Molluscs','Celery','Mustard','Lupin','Sulphites'].map(a=>'<button type="button" class="select-chip '+(selected.includes(a)?'selected':'')+'" aria-pressed="'+selected.includes(a)+'" onclick="toggleAllergen(this)">'+a+'</button>').join('')+'</div><label class="field">Dietary & condition preferences</label><div class="row">'+['Celiac Disease','Halal','Vegetarian'].map((a,i)=>'<label class="check"><input type="checkbox" '+(!i?'checked':'')+'>'+a+'</label>').join('')+'</div><label class="field">“May contain” / traces policy</label><div class="segmented"><button type="button" class="active" onclick="setPolicy(this,&quot;strict&quot;)">Strict: turn Red</button><button type="button" onclick="setPolicy(this,&quot;cautious&quot;)">Cautious: turn Amber</button></div><details><summary>Doctor’s emergency plan & pen expiry</summary><p style="margin-top:14px">Paste only the instructions prescribed by your child’s doctor.</p><textarea placeholder="No doctor’s plan added yet" aria-label="Doctor’s written plan"></textarea><label class="field" for="expiry">Epinephrine pen expiry</label><input type="date" id="expiry" value="2026-11-21"><p>Demo expiry: Nov 2026 · 30-day reminder preview</p><label class="secondary" style="display:inline-block;margin-top:10px">Scan box expiry (photo)<input type="file" accept="image/*" capture="environment" hidden onchange="toast(&quot;Photo selected. Confirm the expiry date manually in this prototype.&quot;)"></label></details><button class="primary wide" type="submit">Save profile '+ico('arrow')+'</button></form>',
scan:()=>heading('ONE LABEL. A LITTLE MORE CERTAINTY.',txt('Let’s check a product','لنَفحص المنتج'),'Scan a barcode, then compare both ingredient labels.')+'<div class="content stack"><div class="row spread"><button class="secondary" onclick="go(&quot;home&quot;)">✕ Close</button><span style="font-size:11px;color:#6e8278">'+ico('lock')+' Cropping removes GPS & EXIF data</span></div><div class="segmented">'+['Barcode','Original label','Arabic sticker'].map((x,i)=>'<button class="'+(scanStep===i?'active':'')+'" onclick="scanStep='+i+';render()">'+x+'</button>').join('')+'</div><div class="camera"><span class="camera-hint">SAMPLE LABEL · Keep every ingredient inside the frame</span><div class="label-photo"><b>INGREDIENTI · HAZELNUT WAFER</b><br>Farina di frumento, zucchero, cacao,<br>pasta di sesamo, lecitina (E322).<br><strong>Può contenere frutta a guscio.</strong><br><small>المكونات: دقيق القمح، سكر، كاكاو، طحينة</small></div></div><div class="warning">⚠ List looks cut off on the right edge — please retake for a complete check. Incomplete labels never receive a Green verdict.</div><div class="steps"><div>✓ Barcode</div><div>✓ Original label<br>Captured: Italian</div><div>③ Add Arabic sticker</div></div><div class="row"><button class="secondary" onclick="startCamera()">'+ico('scan')+' Open camera</button><label class="secondary">Upload label<input type="file" accept="image/*" capture="environment" hidden onchange="previewFile(this)"></label><button class="primary" onclick="go(&quot;verdict&quot;)">Explore sample result '+ico('arrow')+'</button></div><p style="font-size:11px">Camera preview is local. OCR, barcode lookup, and label analysis are not connected in this design prototype.</p></div>',
verdict:()=>heading('THE LABEL TELLS A BIGGER STORY',txt('A second look is needed','نحتاج إلى نظرة أخرى'),'Sample scan · Original Italian label + Arabic import sticker')+'<div class="content stack"><div class="big-card"><div class="row"><span class="product" style="width:65px;height:75px;font-size:38px">🍫</span><div><h2>Imported Hazelnut Wafer</h2><p>Scanned by Grandma · just now</p></div></div><div class="row" style="margin-top:20px"><span class="status red" style="padding:12px">● Sara: RED · Avoid</span><span class="status amber" style="padding:12px">● Omar: AMBER · Verify</span></div></div><div class="danger-box"><h3>⚠ Sticker discrepancy alert</h3><p style="margin-top:8px">An important warning is missing from the Arabic sticker.</p><div class="compare"><div><small>Original Italian label</small>“Può contenere frutta a guscio”<br><b>May contain tree nuts</b></div><div><small>Arabic sticker · الملصق العربي</small><b style="color:var(--red)">Missing warning!</b><br>تحذير المكسرات غير موجود</div></div></div><div class="big-card"><h3>Hidden ingredients, made visible</h3><div class="activity"><div><h4>Tahini / طحينة → Sesame / سمسم</h4><p>Quoted label ingredient · matches Sara’s avoided allergen</p></div><span class="status red">Avoid</span></div><div class="activity"><div><h4>E322 · Lecithin</h4><p>Source unknown. Soy or egg source is unverified.</p></div><span class="status amber">Verify</span></div></div><div class="big-card"><div class="row spread"><h3>What this means</h3><button class="secondary" onclick="readVerdict()">'+ico('sound')+' Read aloud</button></div><p style="margin-top:12px">The label lists sesame, which Sara avoids. The sticker omits the tree-nut warning. E322 has no stated source, so Omar’s check remains uncertain.</p><p dir="rtl" style="margin-top:12px">المنتج يحتوي على السمسم الذي تتجنبه سارة. تحذير المكسرات مفقود من الملصق العربي، ومصدر الليسيثين غير معروف.</p></div><div class="warning">Sara’s Red result cannot be overridden. Parent approval is available only for an Amber result.</div><button class="primary" style="background:#d97706" onclick="showApproval()">View “Ask Sara’s Mum” Amber scenario '+ico('arrow')+'</button><p style="text-align:center;font-size:12px">A check, not a guarantee · فحص وليس ضماناً</p></div>',
safe:()=>heading('THE FAMILY FAVOURITES',txt('A little list of reassurance','قائمة للاطمئنان'),'Approved recipes, kept close. Always check the latest label.')+'<div class="content stack"><input type="search" placeholder="Search your family safe list…" aria-label="Search safe list" oninput="filterProducts(this.value)"><div class="row">'+['Everyone','Sara','Omar'].map(n=>'<button class="select-chip '+(filter===n?'selected':'')+'" onclick="filter=&quot;'+n+'&quot;;render()">'+n+'</button>').join('')+'</div>'+(!removed?'<div class="warning" id="recipe-alert"><span class="status amber">RECIPE CHANGE ALERT</span><h2 style="margin-top:12px">Hummus Crackers</h2><p>Ingredient list changed since you approved it on Oct 10.</p><div class="chips" style="margin:15px 0"><span class="chip rose">+ Whey powder (Milk)</span><span class="chip rose">+ Tahini (Sesame)</span></div><button class="secondary" onclick="go(&quot;verdict&quot;)">Review changes</button> <button class="danger-btn" onclick="removed=true;render();toast(&quot;Hummus Crackers removed from this demo safe list&quot;)">Remove from safe list</button></div>':'')+'<div class="big-card" id="products">'+safeProducts()+'</div><p style="font-size:11px">Sample approvals only. Green refers to the recorded recipe, never a guarantee of safety.</p></div>',
emergency:()=>emergencyView('emergency'),cook:()=>emergencyView('cook'),child:()=>emergencyView('child'),
onboarding:()=>heading('WELCOME TO YOUR CIRCLE OF CARE',txt('A safer start, together.','بداية أكثر أماناً، معاً.'),'No accounts. No passwords. Just the people who care.')+'<div class="content stack"><div class="big-card"><h2>'+ico('shield')+' Privacy by design</h2><div class="activity"><div><h4>01 · Allergies belong on your phone</h4><p>This prototype keeps entered profiles in memory. Production encryption is planned.</p></div></div><div class="activity"><div><h4>02 · The label, never the child</h4><p>No AI requests are sent in this demo. Cropped-label-only processing is the production design.</p></div></div><div class="activity"><div><h4>03 · Built with Jordanian families in mind</h4><p>Jordan’s Personal Data Protection Law is a design requirement; legal compliance has not been assessed.</p></div></div><label class="check"><input id="consent" type="checkbox" onchange="document.querySelectorAll(&quot;.consent-action&quot;).forEach(b=>b.disabled=!this.checked)">I am a parent or guardian and consent to setting up a profile on this device.</label><div class="row"><button disabled class="primary consent-action" onclick="go(&quot;profile&quot;)">Create new family circle</button><button disabled class="secondary consent-action" onclick="showJoin()">Join as caregiver · Scan QR</button></div></div><div class="big-card"><h3>You’re always in control.</h3><p style="margin:10px 0">Delete the demo profiles and reset this session whenever you like.</p><button class="secondary" style="color:var(--red)" onclick="showDelete()">Delete everything</button></div></div>'};
function activity(em,n,t,s,c,p){return '<button class="activity wide" style="text-align:start" onclick="go(&quot;'+p+'&quot;)"><span class="product">'+em+'</span><div><h4>'+n+'</h4><p>'+t+'</p></div><span class="status '+c+'">'+s+'</span></button>'}function safeProducts(q=''){let items=[['🌾','Organic oat flakes','Sara · Omar'],['🥛','Almond drink','Sara · Omar'],['🍚','Basmati rice','Sara · Omar'],['🍘','Plain rice cakes','Sara']].filter(x=>x[1].toLowerCase().includes(q.toLowerCase())&&(filter==='Everyone'||x[2].includes(filter)));return approvedRecipes.filter(n=>n.toLowerCase().includes(q.toLowerCase())).map(n=>'<div class="activity"><span class="product">🍪</span><div><h4>'+n+'</h4><p>Parent decision · source still unverified</p></div><span class="status amber">Approved · Verify</span></div>').join('')+items.map(x=>'<div class="activity"><span class="product">'+x[0]+'</span><div><h4>'+x[1]+'</h4><p>'+x[2]+' · Recipe checked Oct 10</p></div><span class="status green">✓ Approved</span></div>').join('')||'<p class="empty">No products match your search.</p>'}function filterProducts(q){$('#products').innerHTML=safeProducts(q)}
function emergencyView(tab){return heading('CARE, WHEN IT MATTERS MOST',txt('Always within reach','دائماً في متناول يدك'),'Sara’s care card · سارة')+'<div class="content"><div class="segmented">'+[['emergency','🚨 Emergency mode'],['cook','♧ Tell the cook'],['child','☺ Child mode']].map(([p,n])=>'<button class="'+(tab===p?'active':'')+'" onclick="go(&quot;'+p+'&quot;)">'+n+'</button>').join('')+'</div>'+(tab==='emergency'?'<div class="stack"><a class="danger-btn wide" style="font-size:26px;text-align:center;padding:25px" href="tel:911">'+ico('phone')+' Call 911 Now · اتصل بالطوارئ</a><button class="secondary wide" onclick="emergencySMS()">Send emergency SMS to family</button><p style="font-size:11px">Opens your SMS app for you to choose recipients and send. Location is requested only when tapped.</p><div class="big-card"><h2>Doctor’s written action plan</h2><h3 dir="rtl">خطة الطوارئ المكتوبة من الطبيب</h3><div class="warning" style="margin:18px 0">No doctor’s plan has been added. Do not use this demo as treatment instructions.</div><p>Keep the child’s prescribed medicine and clinician’s exact instructions here.</p><p dir="rtl">أضف تعليمات الطبيب والأدوية الموصوفة لطفلك هنا.</p><button class="primary" style="margin-top:20px" onclick="go(&quot;profile&quot;)">Add doctor’s plan</button></div><div class="notice" style="margin:0"><h3>'+ico('bell')+' Epinephrine pen expires in 28 days</h3><p>Sample expiry: 21 Nov 2026 · Reminder preview</p></div></div>':tab==='cook'?'<div class="big-card"><div class="eyebrow">PLEASE SHOW THIS CARD TO THE CHEF</div><h2>Please help keep our meal safe.</h2><h2 dir="rtl">يرجى مساعدتنا في تحضير وجبة آمنة</h2><p>Family dining card · Sara and Omar. Please check ingredients and avoid cross-contact.</p><div class="cook-list"><div>Sesame · Tahini<span>سمسم · طحينة</span></div><div>Milk · Samneh · Jameed<span>حليب · سمنة · جميد</span></div><div>Wheat · Bulgur · Freekeh<span>قمح · برغل · فريكة</span></div><div>Peanuts · Pine nuts (check)<span>فول سوداني · صنوبر (تحقق)</span></div></div><p dir="rtl">يرجى التحقق من المكونات وتجنب التلامس مع مسببات الحساسية. أخبرنا إن لم تكن متأكداً.</p><button class="primary wide" style="margin-top:20px" onclick="speak(&quot;Please check for sesame, milk, wheat, and peanuts. Please avoid cross contact.&quot;)">'+ico('sound')+' Read to the cook</button></div>':'<div class="big-card" style="text-align:center;background:#fff2f0"><div class="child-face">🙁</div><h1 style="color:var(--red)">Stop. Ask a grown-up.</h1><p dir="rtl">توقف واسأل شخصاً بالغاً</p><p>This sample wafer contains sesame.</p><button class="danger-btn" style="margin-top:25px" onclick="speak(&quot;Stop. Ask a grown-up. This food contains sesame.&quot;)">'+ico('sound')+' Listen</button></div>')+'</div>'}
function modal(body){document.body.insertAdjacentHTML('beforeend','<div class="modal-wrap" role="dialog" aria-modal="true" aria-label="Family action"><div class="modal"><button class="close" onclick="closeModal()" aria-label="Close dialog">×</button>'+body+'</div></div>');$('.modal .close').focus()}function closeModal(){$('.modal-wrap')?.remove()}function showApproval(){modal('<div class="eyebrow">ASK & APPROVE · SIMULATED PARENT PHONE</div><h2>Urgent check from Grandma</h2><p>Grandma scanned <b>Cocoa Biscuits</b> for Sara. This separate Amber example has no confirmed avoided ingredient.</p><div class="label-photo">INGREDIENTS: cocoa, sugar,<br><mark>lecithin — source not specified</mark><br><mark>Manufacturing information unclear</mark></div><p><span class="status amber">Amber · unknown source</span> Please verify with the manufacturer. Approval records a parent decision; it does not change the evidence.</p><label class="check"><input id="save-recipe" type="checkbox">Save this exact recipe to Family Safe List</label><div class="stack"><button class="danger-btn" onclick="decision(false)">Refuse · Unsafe for Sara</button><button class="primary" style="background:#16a34a" onclick="decision(true)">Approve product</button></div>')}function decision(ok){let save=$('#save-recipe').checked;if(ok&&save&&!approvedRecipes.includes('Cocoa Biscuits'))approvedRecipes.push('Cocoa Biscuits');closeModal();modal('<div class="eyebrow">SIMULATED REPLY RECEIVED</div><h2>'+(ok?'Parent approved this recipe':'Product refused')+'</h2><p>'+(ok?'Grandma’s demo request now shows the parent’s decision. The underlying uncertainty remains.':'Grandma’s demo request now shows Red: do not serve.')+'</p><span class="status '+(ok?'amber':'red')+'">'+(ok?'Parent-approved · still unverified':'RED · Refused')+'</span><p>'+(save&&ok?'Recipe marked for the demo safe list. No real family notification was sent.':'No real family notification was sent.')+'</p><button class="primary wide" onclick="closeModal()">Done</button>')}
function showInvite(){modal('<div class="eyebrow">A LITTLE MORE CARE</div><h2>Invite a caregiver</h2><div style="text-align:center;padding:25px;color:var(--teal)">'+ico('qr')+'</div><p>Encrypted QR circle invitations are part of the production design. This prototype does not generate a usable encryption key or invite.</p><div class="warning">No login. No email. Share a future invitation only with a trusted caregiver.</div><button class="primary wide" style="margin-top:20px" onclick="closeModal();go(&quot;onboarding&quot;)">Explore caregiver setup</button>')}function showJoin(){modal('<h2>Join your family circle</h2><p>A parent will show you their encrypted invitation QR. Secure QR pairing is not connected in this prototype.</p><button class="primary wide" onclick="closeModal();go(&quot;family&quot;)">Explore sample family circle</button>')}function showDelete(){modal('<h2>Delete this demo session?</h2><p>This resets sample selections and removes any entered profile name from memory.</p><button class="danger-btn wide" onclick="memberName=&quot;&quot;;selected=[];savedProfiles=[];approvedRecipes=[];removed=true;closeModal();render();toast(&quot;Entered profile data cleared&quot;)">Delete everything</button>')}
function toggleAllergen(b){let a=b.textContent;selected=selected.includes(a)?selected.filter(x=>x!==a):[...selected,a];b.classList.toggle('selected');b.setAttribute('aria-pressed',selected.includes(a))}function setPolicy(b,p){policy=p;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function saveProfile(){memberName=esc($('#name').value.trim());let plan=$('textarea').value;let expiry=$('#expiry').value;savedProfiles=savedProfiles.filter(x=>x.name!==memberName);savedProfiles.push({name:memberName,allergens:[...selected],policy,plan:esc(plan),expiry});toast('Profile saved for this session');go('family')}function readVerdict(){speak(arabic?'المنتج يحتوي على السمسم الذي تتجنبه سارة. مصدر الليسيثين غير معروف.':'The label lists sesame, which Sara avoids. The Arabic sticker is missing the nut warning. Lecithin source is unknown. A check, not a guarantee.')}
async function startCamera(){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});$('.camera').innerHTML='<video autoplay playsinline muted></video><span class="camera-hint">Local preview only · analysis not connected</span>';$('.camera video').srcObject=stream}catch(e){toast('Camera unavailable. Upload a label photo or explore the sample.')}}function previewFile(input){let f=input.files[0];if(!f)return;let u=URL.createObjectURL(f);$('.camera').innerHTML='<img alt="Your label preview — not analyzed" style="max-width:100%;max-height:300px" src="'+u+'">';toast('Photo preview only. No analysis or upload occurred.');$('.camera img').onload=()=>URL.revokeObjectURL(u)}function emergencySMS(){let open=loc=>{let body='EMERGENCY: Sara had a reaction after eating [Product] at '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+'. Location: '+loc;location.href='sms:?body='+encodeURIComponent(body)};if(navigator.geolocation)navigator.geolocation.getCurrentPosition(p=>open('https://maps.google.com/?q='+p.coords.latitude+','+p.coords.longitude),()=>open('[Location unavailable — add manually]'),{timeout:8000});else open('[Add location]')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){let f=[...$('.modal').querySelectorAll('button,input,a')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});const originalFamily=views.family;views.family=()=>originalFamily()+(savedProfiles.length?'<div class="big-card" style="margin-top:20px"><h2>Saved in this session</h2>'+savedProfiles.map(p=>'<div class="activity"><div><h3>'+p.name+'</h3><p>'+p.allergens.join(' · ')+'</p><p>Traces: '+p.policy+'</p></div></div>').join('')+'</div>':'');render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
